"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4832],{65162:e=>{e.exports=JSON.parse('{"functions":[{"name":"Initialize","desc":"Splits built/locked platforms, publishes ghosts, sets the progress\\nattributes and binds `ReqPlatformDeposit`. Call once from\\nPlatformExtendLoader. Platform order is found here: the Model named\\n`PlatformConfig.FRONT_PLATFORM_NAME` is index 1, the rest are numbered by\\ndistance from it, and each gets a `PlatformIndex` attribute.","params":[],"returns":[],"function_type":"static","source":{"line":173,"path":"src/ServerStorage/SharedModules/PlatformExtendService.luau"}},{"name":"DevBuildNext","desc":"Dev/testing: builds the next locked platform at once, with no cost. Callers\\nmust gate this themselves (see DevCommandsService). Returns the built\\nPlatformIndex, or nil when every platform already exists.","params":[],"returns":[{"desc":"","lua_type":"number?\\n"}],"function_type":"static","source":{"line":262,"path":"src/ServerStorage/SharedModules/PlatformExtendService.luau"}}],"properties":[],"types":[],"name":"PlatformExtendService","desc":"Owns which train platforms exist. At boot it keeps the first\\n`PlatformConfig.STARTING_PLATFORMS` platforms in `Workspace.TrainPlatforms`,\\nmoves the rest to `ServerStorage`, and publishes tag-free ghost copies to\\n`ReplicatedStorage` for the client preview. `ReqPlatformDeposit` moves pool\\nWood/Metal into the next platform; when both are full the platform is\\nparented back into the world. Progress lives in attributes on\\n`TrainPlatforms`, which replicate to late joiners (no JoinSync sender).\\n\\nDouble submits are safe: the handler reads and writes all state with no\\nyield, and Roblox runs handlers one at a time, so a second same-frame\\nrequest sees the updated totals.","realm":["Server"],"source":{"line":18,"path":"src/ServerStorage/SharedModules/PlatformExtendService.luau"}}')}}]);